// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;
    function setUp() public { c = new airPort(); }

    // Fuzz the caller (from), the value v, and the single recipient candidate `to`.
    // The distinguishing inputs are those where _tos.length == 1. We let the fuzzer
    // pick values; we only restrict that the recipient is not the zero address
    // (zero-address recipients are still admissible to the reference but less useful).
    function testFuzz_property(address from, address to, uint256 v) public {
        vm.assume(to != address(0)); // keep domain wide but avoid trivial zero-address

        // Build a single-recipient array: this is the crucial distinguishing case
        address[] memory tos = new address[](1);
        tos[0] = to;

        // We need the callee at caddress to accept the low-level call and return true.
        // A raw fuzzed address would be an EOA and calls to it would succeed but record nothing.
        // Here we deploy a RecordingReceiver that implements the exact signature
        // transferFrom(address,address,uint256) and returns true. This matches what
        // C calls via abi.encodeWithSelector and lets the call succeed.
        RecordingReceiver rec = new RecordingReceiver();
        address caddress = address(rec);

        // Call transfer and observe whether it returns (ok=true) or reverts (ok=false).
        bool ok;
        try c.transfer(from, caddress, tos, v) returns (bool r) {
            ok = true;
            // also assert that the reference returns true when it completes
            // (the reference's implementation always returns true after successful calls)
            assert(r == true);
        } catch {
            ok = false;
        }

        // GENERAL RULE (assertion): For every admissible input with a single recipient
        // (i.e. tos.length == 1), the reference contract completes (ok == true).
        // The mutant with require(_tos.length > 1) will make such calls revert for some inputs,
        // so this assertion will fail on the mutant for at least those fuzzed inputs.
        assertTrue(ok);

        // Additionally ensure the recorder observed exactly one call and that its decoded
        // arguments match what C was supposed to send (this reads the helper's public state).
        // This is still observing c's external behavior via the recorder.
        assertTrue(rec.callsCount() == 1);
        (address recordedFrom, address recordedTo, uint256 recordedV) = rec.lastArgs();
        assertTrue(recordedFrom == from);
        assertTrue(recordedTo == to);
        assertTrue(recordedV == v);
    }
}

// A minimal recording helper that exposes the exact function selector
// transferFrom(address,address,uint256) so C's low-level call is decoded
// and recorded. It returns true so the call in the reference succeeds.
contract RecordingReceiver {
    uint256 public calls;
    address public lastFrom;
    address public lastTo;
    uint256 public lastV;

    // Match the selector bytes4(keccak256("transferFrom(address,address,uint256)"))
    function transferFrom(address from, address to, uint256 v) external returns (bool) {
        calls += 1;
        lastFrom = from;
        lastTo = to;
        lastV = v;
        return true;
    }

    function callsCount() external view returns (uint256) { return calls; }
    function lastArgs() external view returns (address, address, uint256) {
        return (lastFrom, lastTo, lastV);
    }
}
